<?php
namespace App\Http\Middleware;use App\Services\DeviceCredentialAuthenticator;use Closure;use Illuminate\Http\Request;use Symfony\Component\HttpFoundation\Response;
class AuthenticateDeviceCredential { public function __construct(private DeviceCredentialAuthenticator $authenticator){}public function handle(Request $request,Closure $next,?string $scope=null):Response{$credential=$this->authenticator->authenticate($request->bearerToken());if(!$credential)return response()->json(['message'=>'Unauthenticated.'],401);if($scope&&!$credential->hasScope($scope))return response()->json(['message'=>'This Device Credential lacks the required scope.'],403);$request->attributes->set('deviceCredential',$credential);$request->attributes->set('device',$credential->device);return $next($request);} }
